-- 上外(sufe)必修一 情景闯关题(context_questions, grade=10, volume='required2', publisher='sufe')。Aaron 跑。幂等(只删 sufe 本册)。
BEGIN;
DELETE FROM public.context_questions WHERE publisher='sufe' AND volume='required2';

COMMIT;
SELECT unit, count(*) FROM public.context_questions WHERE publisher='sufe' AND volume='required2' GROUP BY unit ORDER BY unit;
SELECT count(*) AS context_q_sufe_required2 FROM public.context_questions WHERE publisher='sufe' AND volume='required2';
